contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // We take an amount to forward to c.go. The test contract must have enough balance to send that amount.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance for test");
        // observe before-values
        uint beforeBalance = address(c).balance;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;

        // General rule:
        // - If the call succeeded (not reverted) then c.balance is zero afterwards and owner unchanged.
        // - If the call reverted then c.balance remains equal to beforeBalance (no ETH moved) and owner unchanged.
        assert(afterOwner == beforeOwner && ( (!reverted && afterBalance == 0) || (reverted && afterBalance == beforeBalance) ));
    }

    receive() external payable { }
}

