pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeBalance = address(c).balance;
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        assertTrue(afterOwner == beforeOwner && ( (!reverted && afterBalance == 0) || (reverted && afterBalance == beforeBalance) ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
